<template>
 <section class="qvs-page" :data-variant="appearance.variant" aria-labelledby="qvs-title">
  <header class="qvs-hero"><div><span class="qvs-kicker">QGAUSS / LET YOUR WORDS FIND A VOICE</span><h1 id="qvs-title">把心里的文字，<em>说给世界听。</em></h1><p>给故事一点温度，给好点子一段被听见的时间。</p><router-link to="/voice">去声音收藏室，重听一次喜欢的回响 <ClientIcon name="arrowUpRight"/></router-link></div><div class="qvs-headphones" aria-hidden="true"><i></i><i></i><b>♪</b><span>GOOD WORDS, GOOD VIBES</span></div></header>
  <p v-if="state.notice" class="qvs-notice" role="status">{{ state.notice }}</p><p v-if="state.error" class="qvs-error" role="alert">{{ state.error }}</p>
  <div v-if="state.loading" class="qvs-loading" role="status"><QLoader :size="29"/>正在打开声音工作室…</div>
  <p v-else-if="!state.options?.speech?.ready" class="qvs-unavailable" role="status">{{ state.options?.speech?.reason||'创作搭档尚未接通，可以先把文字留在这里。' }}<button type="button" @click="work.loadOptions">重新读取</button></p>
  <div class="qvs-workspace">
   <section class="qvs-writing" aria-label="配音文字"><header><div><span class="qvs-kicker">FIRST, A LITTLE SOMETHING TO SAY</span><h2>今天，想说点什么？</h2></div><span class="qvs-paper-stamp" aria-hidden="true">✳</span></header><label class="qvs-title-input">给这段声音起个名字<input v-model="state.draft.title" maxlength="80" placeholder="例如：写给明天的自己"/></label><label class="qvs-text-input"><span>写下要说的话 <small>{{ state.draft.text.length }} / {{ state.options?.maxSpeechChars||16000 }} 字符</small></span><textarea v-model="state.draft.text" maxlength="32768" rows="13" placeholder="把故事、旁白、小计划，或一句想认真说的话，放在这里。"/></label><footer><span><i></i>草稿留在当前账号的此窗口中</span><button type="button" class="qvs-clear" :disabled="!state.draft.text&&!state.draft.title" @click="state.clearReview=true">整理这张纸</button></footer></section>
   <aside class="qvs-voices" aria-label="选择配音音色"><header><span class="qvs-kicker">A VOICE THAT FEELS RIGHT</span><h2>挑一种，<em>喜欢的语气。</em></h2><p>同一段文字，也有不同的温度。</p></header><div class="qvs-voice-grid"><button v-for="voice in VOICES" :key="voice.id" type="button" :aria-pressed="state.draft.voice===voice.id" :style="{'--voice-color':voice.color}" @click="state.draft.voice=voice.id"><span class="qvs-voice-orb" aria-hidden="true">{{ voice.id==='fable'?'◡':voice.id==='nova'?'✦':voice.id==='echo'?'◉':voice.id==='onyx'?'◒':voice.id==='shimmer'?'✧':'⌁' }}</span><span><strong>{{ voice.name }}</strong><small>{{ voice.mood }}</small></span><i>{{ state.draft.voice===voice.id?'✓':'+' }}</i></button></div><div class="qvs-voice-note"><p>{{ selectedVoice.note }}</p><button type="button" :disabled="busy||!!state.offer||!state.options?.speech?.ready" @click="work.quote(true)"><ClientIcon name="microphone"/>先听听{{ selectedVoice.name }}的声音</button><small>试听使用固定介绍文字，也会先确认本站次数。</small></div></aside>
   <section class="qvs-session" aria-label="声音创作与回放"><div class="qvs-console-art" :class="{'is-playing':state.playing,'is-working':busy}" aria-hidden="true"><div class="qvs-record"><i></i><b>Q</b></div><div class="qvs-wave"><i v-for="n in 23" :key="n" :style="{'--bar':n}"></i></div><span>{{ busy?'A LITTLE MAGIC, IN THE MAKING':'YOUR WORDS. YOUR OWN LITTLE WORLD.' }}</span></div>
    <div class="qvs-session-body"><span class="qvs-kicker">{{ state.task?'ONE LITTLE MOMENT, SAVED':'MAKE A LITTLE ROOM FOR SOUND' }}</span><h2>{{ state.task?voiceTaskLabel(state.task):state.pending?'先把这一次声音，核对好。':'好文字，值得被好好听见。' }}</h2><p v-if="state.task">{{ state.task.sourceKind==='sample'?'音色试听':state.task.label||'这一段声音' }} · {{ voiceName(state.task.voice) }}</p><p v-else>准备好后，核对文字、音色和次数，再让创作开始。</p>
     <template v-if="state.task"><div v-if="!voiceTerminal(state.task)" class="qvs-progress" role="status"><QLoader :size="22"/><span>已完成 {{ state.task.completedSegments||0 }} / {{ state.task.segmentCount||1 }} 段 · {{ state.task.progress||0 }}%</span></div><div v-if="state.task.status==='COMPLETED'&&state.task.audio?.length" class="qvs-player"><div class="qvs-player-controls"><button type="button" class="qvs-play" :aria-label="state.playing?'暂停这段配音':'播放这段配音'" :disabled="state.audioLoading" @click="work.play"><QLoader v-if="state.audioLoading" :size="24"/><span v-else>{{ state.playing?'Ⅱ':'▶' }}</span></button><div><strong>第 {{ state.part+1 }} / {{ state.task.audio.length }} 段</strong><small>{{ voiceDuration(state.playbackSeconds) }} / {{ voiceDuration(state.playbackDuration) }}</small></div><button type="button" aria-label="上一段配音" :disabled="!state.part||state.audioLoading" @click="work.playPart(state.part-1)">‹</button><button type="button" aria-label="下一段配音" :disabled="state.part+1>=state.task.audio.length||state.audioLoading" @click="work.playPart(state.part+1)">›</button></div><input type="range" min="0" :max="state.playbackDuration||0" :value="state.playbackSeconds" step="0.1" aria-label="配音播放进度" :disabled="!state.audioUrl||!state.playbackDuration" @input="work.seek($event.target.value)"/><label class="qvs-speed">播放语速<select v-model.number="state.playbackRate"><option :value=".75">0.75 ×</option><option :value="1">1 ×</option><option :value="1.25">1.25 ×</option><option :value="1.5">1.5 ×</option></select><small>只改变回放，不重新生成。</small></label></div><p v-if="state.task.errorMessage" class="qvs-inline-error" role="status">{{ state.task.errorMessage }}</p><div v-if="state.task.billing" class="qvs-billing"><span>已使用 <b>{{ state.task.billing.charged||0 }} 次</b></span><span v-if="state.task.billing.reserved">当前预留 <b>{{ state.task.billing.reserved }} 次</b></span><span v-if="state.task.billing.returned">已退回 <b>{{ state.task.billing.returned }} 次</b></span></div></template>
     <div class="qvs-session-actions"><button v-if="!state.pending||state.task&&voiceTerminal(state.task)" type="button" class="qvs-primary" :disabled="busy||!!state.offer||!state.draft.text.trim()||!state.options?.speech?.ready" @click="work.quote(false)">让文字，慢慢响起来 <ClientIcon name="arrowUpRight"/></button><template v-if="state.pending&&state.stage==='unknown'"><button type="button" class="qvs-primary" @click="work.check">核对原任务</button><button type="button" class="qvs-secondary" @click="work.retry">重试原提交</button></template><button v-if="state.pending||state.task&&!voiceTerminal(state.task)" type="button" class="qvs-secondary" :disabled="state.stopping" @click="work.stop">{{ state.stopping?'正在确认停止结果…':state.task?'请求停止生成':'结束这次等待' }}</button><button v-if="state.task?.status==='COMPLETED'&&state.task.audio?.length" type="button" class="qvs-secondary" :disabled="state.downloading" @click="work.download"><QLoader v-if="state.downloading" :size="19"/>{{ state.downloading?'正在整理整段声音…':'保存完整配音' }}</button><router-link v-if="state.task" to="/voice" class="qvs-text-link">在声音收藏室找到它 <ClientIcon name="arrowUpRight"/></router-link></div><p class="qvs-disclosure">合成声音 · 本站次数以生成回执为准。重听和保存已经完成的声音，不会重新生成或扣次。</p>
    </div><audio ref="audio" :src="state.audioUrl||undefined" preload="none" @loadedmetadata="work.metadata" @timeupdate="work.timeUpdate" @ended="work.nextPart" @error="work.audioError"></audio>
   </section>
  </div>
  <dialog ref="review" class="qvs-review" aria-labelledby="qvs-review-title" @cancel.prevent="work.reject"><template v-if="state.offer"><span class="qvs-kicker">ONE LAST LOOK, THEN LET IT SING</span><h2 id="qvs-review-title">{{ state.offer.payload.sample?'先听一小段，感受它的语气。':'让这段文字，拥有自己的声音。' }}</h2><div class="qvs-offer-title"><b>{{ voiceName(state.offer.payload.voice) }}</b><span>{{ state.offer.payload.sample?'固定介绍文字':state.offer.payload.title||'这一次配音' }}</span></div><div v-if="!state.offer.payload.sample" class="qvs-offer-text">{{ state.offer.payload.text }}</div><div v-if="state.offer.loading" class="qvs-offer-loading" role="status"><QLoader :size="23"/>正在确认这一次的次数…</div><template v-else-if="state.offer.quote"><p class="qvs-offer-price">{{ voiceCharge(state.offer.quote) }}</p><p>共 {{ state.offer.quote.chars }} 字符，将分成 {{ state.offer.quote.segments }} 段生成。整次完成后只结算本次确认的次数。</p></template><p v-if="state.offer.error" class="qvs-inline-error" role="alert">{{ state.offer.error }}</p><small>这份确认使用上面保存的内容。编辑区的新修改会继续保留。</small><footer><button type="button" class="qvs-secondary" @click="work.reject">再想一想</button><button type="button" class="qvs-primary" :disabled="state.offer.loading||!state.offer.quote||!!state.offer.error" @click="work.approve">确认，开始生成 <ClientIcon name="arrowUpRight"/></button></footer></template></dialog>
  <dialog ref="clearDialog" class="qvs-review" aria-labelledby="qvs-clear-title" @cancel.prevent="state.clearReview=false"><h2 id="qvs-clear-title">给下一个想法，腾出一张纸？</h2><p>只会清空当前编辑区。已经提交的声音任务和收藏室记录会继续保留。</p><footer><button type="button" class="qvs-secondary" @click="state.clearReview=false">先留着</button><button type="button" class="qvs-primary" @click="work.clearDraft">清空这张纸</button></footer></dialog>
  <dialog ref="transferDialog" class="qvs-review" aria-labelledby="qvs-transfer-title" @cancel.prevent="work.keepDraft"><h2 id="qvs-transfer-title">把收藏室的这段文字，带到这里？</h2><p>当前编辑区还有内容。你可以保留它，或明确换成刚才选择的那一段。</p><footer><button type="button" class="qvs-secondary" @click="work.keepDraft">保留当前文字</button><button type="button" class="qvs-primary" @click="work.adoptTransfer">换成收藏室的文字</button></footer></dialog>
 </section>
</template>
<script setup>
import {computed,ref,watch,nextTick} from 'vue';
import {VOICES,voiceName,voiceDuration,voiceCharge,voiceTerminal,voiceTaskLabel} from '../lib/voice-presentation.js';
import {useAppearance} from '../stores/appearance.js';
import {useVoiceComposer} from '../composables/useVoiceComposer.js';
import ClientIcon from '../components/reference/ClientIcon.vue';
import QLoader from '../components/QLoader.vue';
import '../components/design/voice-composer.css';
const appearance=useAppearance(),audio=ref(null),review=ref(null),clearDialog=ref(null),transferDialog=ref(null),work=useVoiceComposer(audio),{state,busy}=work;
const selectedVoice=computed(()=>VOICES.find(row=>row.id===state.draft.voice)||VOICES[2]);
for(const [value,element]of [[()=>state.offer,review],[()=>state.clearReview,clearDialog],[()=>state.transfer,transferDialog]])watch(value,async open=>{await nextTick();if(open&&!element.value?.open)element.value?.showModal?.();else if(!open&&element.value?.open)element.value.close();});
</script>
